omer by replying to the bot's message about the ticket.\n    const quoted = m.reply_to_message && m.reply_to_message.text ? m.reply_to_message.text : '';\n    const ref = /ID: (T[0-9A-Z-]+)/.exec(quoted);\n    if (ref && m.text) return out({ channel: 'telegram', kind: 'team_reply', text: clip(m.text, 4000), callback: { ticket: ref[1], by: [m.from.first_name, m.from.last_name].filter(Boolean).join(' ') } });\n    return out({ channel: 'telegram', kind: 'ignore' });\n  }\n  if (m.chat.type && m.chat.type !== 'private') return out({ channel: 'telegram', kind: 'ignore' });\n  const name = [m.from && m.from.first_name, m.from && m.from.last_name].filter(Boolean).join(' ') || (m.from && m.from.username) || '';\n  const customer = { id: 'tg:' + m.from.id, name, telegram_chat: String(m.chat.id) };\n  if (/^\\/start\\b/.test(m.text || '')) return out({ channel: 'telegram', kind: 'greet', customer });\n  const media = m.photo ? '[фото]' : m.voice ? '[голосовое сообщение]' : m.document ? '[файл]' : m.video ? '[видео]' : m.sticker ? '[стикер]' : '';\n  const text = clip(m.text || m.caption || '', 4000);\n  if (!text && !media) return out({ channel: 'telegram', kind: 'ignore' });\n  return out({ channel: 'telegram', kind: 'message', customer, text: [media, text].filter(Boolean).join(' '), has_media: Boolean(media) });\n}\n\n// Email\nconst fromRaw = item.from && typeof item.from === 'object' ? ((item.from.value || [])[0] || {}) : item.from;\nconst fromText = typeof fromRaw === 'string' ? fromRaw : `${fromRaw.name || ''} <${fromRaw.address || ''}>`;\nconst address = emailOf((/<([^>]+)>/.exec(fromText) || [null, fromText])[1]);\nconst sender = fromText.replace(/<[^>]*>/, '').replace(/\"/g, '').trim();\nconst ours = emailOf((/<([^>]+)>/.exec((cfg.email || {}).from || '') || [null, (cfg.email || {}).from || ''])[1]);\nconst subject = clip(item.subject, 200);\n// Never answer robots: bounces, auto-replies and our own messages would start a loop.\nconst robot = !address || address === ours || /^(no-?reply|mailer-daemon|postmaster|bounce|notifications?)@/i.test(address)\n  || /^(auto|automatic reply|автоответ|out of office|недоставлено|undeliverable|delivery status)/i.test(subject)\n  || String((item.headers && (item.headers['auto-submitted'] || item.headers['Auto-Submitted'])) || 'no') !== 'no';\nif (robot) return out({ channel: 'email', kind: 'ignore', subject });\nconst plain = item.textPlain || item.text || String(item.textHtml || item.html || '').replace(/<[^>]+>/g, ' ');\nconst text = clip(freshPart(plain), 4000);\nif (!text) return out({ channel: 'email', kind: 'ignore', subject });\nreturn out({ channel: 'email', kind: 'message', subject, customer: { id: address, name: clip(sender, 120), email: address }, text });\n"
