c) => c.id).join(', ')}, other;`,\n        'urgency — low, normal, high; sentiment — positive, neutral, negative, angry; language — код языка;',\n        'can_answer — true или false; confidence — число от 0 до 1, насколько ответ полностью закрывает вопрос по базе знаний;',\n        'answer — готовый ответ клиенту или пустая строка; summary — суть обращения одной фразой на русском;',\n        'needs_human_reason — если can_answer false, коротко почему.',\n        '',\n        'Категории:', categories,\n        '',\n        'База знаний:', kb || '(пусто)',\n      ].join('\\n') },\n      { role: 'user', content: JSON.stringify({ channel: msg.channel, subject: msg.subject, message: msg.text, earlier: history }) },\n    ],\n  },\n} }];\n"
