        "jsCode": "// Decide — reads the model's answer and chooses: send it, show it to the team as a draft, or hand the case to a person.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Tickets sheet columns. The sheet may start empty: the header is written with the first ticket.\nconst TCOLS = ['id', 'created_at', 'updated_at', 'channel', 'customer', 'name', 'email', 'telegram_chat', 'subject', 'category', 'urgency', 'sentiment',\n  'status', 'summary', 'last_message', 'draft', 'history', 'first_response_at', 'reminded_level', 'assignee', 'kb_answer'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst TLAST = colLetter(TCOLS.length - 1);\nconst ticketRange = () => `${quoteSheet(cfg.tickets_sheet)}!A1:${TLAST}`;\nconst rowRange = (row) => `${quoteSheet(cfg.tickets_sheet)}!A${row}:${TLAST}${row}`;\nconst batchGetUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(ticketRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.faq_sheet)}!A1:B`)}`;\nfunction tableOf(values) {\n  const rows = values || [];\n  const header = rows.length && rows[0][0] === 'id';\n  return { header, rows: header ? rows.slice(1) : [] };\n}\nconst cell = (row, c) => row[TCOLS.indexOf(c)] || '';\nconst rowObject = (row) => Object.fromEntries(TCOLS.map((c) => [c, cell(row, c)]));\nconst ctx = $('Thread').first().json;\nconst msg = ctx.msg;\nconst input = $input.first().json || {};\nconst now = nowMs();\nconst iso = new Date(now).toISOString();\nconst CATS = (cfg.categories || []).map((c) => c.id);\n\nlet ai = null, problem = '';\nconst content = input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content;\nif (content) {\n  try {\n    const text = String(content).replace(/```(json)?/g, '');\n    const p = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));\n    ai = {\n      category: CATS.includes(p.category) ? p.category : 'other',\n      urgency: ['low', 'normal', 'high'].includes(p.urgency) ? p.urgency : 'normal',\n      sentiment: ['positive', 'neutral', 'negative', 'angry'].includes(p.sentiment) ? p.sentiment : 'neutral',\n      can_answer: p.can_answer === true && String(p.answer || '').trim().length > 0,\n      confidence: Math.max(0, Math.min(1, Number(p.confidence) || 0)),\n      answer: String(p.answer || '').trim().slice(0, 3000),\n      summary: String(p.summary || '').slice(0, 300),\n      reason: String(p.needs_human_reason || '').slice(0, 200),\n    };\n  } catch (e) { problem = 'bad_json'; }\n} else problem = input.error ? 'llm_error' : 'no_answer';\nconst result = ai || { category: 'other', urgency: 'normal', sentiment: 'neutral', can_answer: false, confidence: 0, answer: '', summary: '', reason: 'модель не ответила' };\n\n// Sending without a person is the exception: every condition must hold.\nconst lowered = msg.text.toLowerCase();\nconst forbidden = (cfg.forbidden_topics || []).find((w) => w && lowered.includes(w.toLowerCase()));\nconst blockers = [];\nif (cfg.mode !== 'auto') blockers.push('режим черновиков');\nif (!result.can_answer) blockers.push(result.reason || 'нет ответа в базе знаний');\nif (result.confidence < (cfg.confidence_threshold || 0.8)) blockers.push(`уверенность ${Math.round(result.confidence * 100)}%`);\nif (!(cfg.auto_categories || []).includes(result.category)) blockers.push(`категория ${result.category}`);\nif (['negative', 'angry'].includes(result.sentiment)) blockers.push('клиент недоволен');\nif (result.urgency === 'high') blockers.push('срочно');\nif (forbidden) blockers.push(`тема «${forbidden}»`);\nif (msg.has_media) blockers.push('есть вложение');\nconst autoSend = blockers.length === 0;\nconst status = autoSend ? 'answered' : result.can_answer ? 'draft_ready' : 'new';\n\nconst line = `${localText(now)} · клиент: ${msg.text.replace(/\\n+/g, ' ').slice(0, 300)}`;\nconst reply = autoSend ? `\\n${localText(now)} · бот: ${result.answer.replace(/\\n+/g, ' ').slice(0, 300)}` : '';\nconst base = ctx.existing || { id: ctx.id, created_at: iso, channel: msg.channel, customer: msg.customer.id, name: msg.customer.name || '', email: msg.customer.email || '',\n  telegram_chat: msg.customer.telegram_chat || '', subject: msg.subject || '', reminded_level: '0', assignee: '', first_response_at: '', history: '' };\nconst row = Object.assign({}, base, {\n  updated_at: iso, category: result.category, urgency: result.urgency, sentiment: result.sentiment, status,\n  summary: result.summary || base.summary || '', last_message: msg.text.slice(0, 1000), draft: result.can_answer ? result.answer : '',\n  history: `${base.history ? base.history + '\\n' : ''}${line}${reply}`.slice(-4000), reminded_level: '0',\n  kb_answer: result.can_answer ? 'yes' : 'no',\n});\nif (autoSend && !row.first_response_at) row.first_response_at = iso;\nconst values = [TCOLS.map((c) => String(row[c] || ''))];\nconst http = ctx.existing\n  ? { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(ctx.sheet_row))) + '?valueInputOption=RAW', body: { values } }\n  : { method: 'POST', url: sheetUrl(encodeURIComponent(ticketRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS', body: { values: ctx.has_header ? values : [TCOLS, ...values] } };\n\nconst label = { low: 'низкая', normal: 'обычная', high: 'высокая' }[result.urgency];\nconst mood = { positive: 'доволен', neutral: '', negative: 'недоволен', angry: 'раздражён' }[result.sentiment];\nconst who = [msg.customer.name, msg.customer.email || (msg.customer.telegram_chat ? 'Telegram' : '')].filter(Boolean).join(', ') || 'без имени';\nconst team = [\n  `${autoSend ? 'Отвечено ботом' : ctx.existing ? 'Новое сообщение в обращении' : 'Новое обращение'} · ${msg.channel} · срочность: ${label}${mood ? ' · ' + mood : ''}`,\n  `От: ${who}`,\n  msg.subject ? `Тема: ${msg.subject}` : '',\n  `Сообщение: ${msg.text.slice(0, 1200)}`,\n  `Категория: ${result.category}${result.summary ? ' · ' + result.summary : ''}`,\n  autoSend ? `Ответ: ${result.answer.slice(0, 1500)}` : result.can_answer ? `Черновик ответа:\\n${result.answer.slice(0, 1500)}` : 'В базе знаний ответа нет — ответьте сами: ответом на это сообщение.',\n  !autoSend ? `Почему не отправлено: ${blockers.join('; ')}` : '',\n  problem ? `Модель: ${problem}` : '',\n  `ID: ${ctx.id}`,\n].filter(Boolean).join('\\n');\n\nconst ack = (cfg.web || {}).ack || 'Спасибо! Мы получили ваше сообщение и ответим в ближайшее время.';\nreturn [{ json: {\n  id: ctx.id, channel: msg.channel, auto_send: autoSend, status, blockers, ai_problem: problem, category: result.category,\n  http, team_chat: cfg.team_chat_id, team_text: team, show_send_button: !autoSend && result.can_answer,\n  reply_text: autoSend ? result.answer : '', reply_email: msg.customer.email || '', reply_subject: (msg.subject ? (/^re:/i.test(msg.subject) ? msg.subject : 'Re: ' + msg.subject) : ((cfg.email || {}).default_subject || 'Ответ службы поддержки')),\n  reply_chat: msg.customer.telegram_chat || '', web_response: { ok: true, answer: autoSend ? result.answer : '', message: autoSend ? '' : ack, ticket: ctx.id },\n} }];\n"
      },
