      "parameters": {
        "jsCode": "// Act on Ticket — a teammate pressed \"Send\", \"We will answer\", or replied to the bot in the team chat.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Tickets sheet columns. The sheet may start empty: the header is written with the first ticket.\nconst TCOLS = ['id', 'created_at', 'updated_at', 'channel', 'customer', 'name', 'email', 'telegram_chat', 'subject', 'category', 'urgency', 'sentiment',\n  'status', 'summary', 'last_message', 'draft', 'history', 'first_response_at', 'reminded_level', 'assignee', 'kb_answer'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst TLAST = colLetter(TCOLS.length - 1);\nconst ticketRange = () => `${quoteSheet(cfg.tickets_sheet)}!A1:${TLAST}`;\nconst rowRange = (row) => `${quoteSheet(cfg.tickets_sheet)}!A${row}:${TLAST}${row}`;\nconst batchGetUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(ticketRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.faq_sheet)}!A1:B`)}`;\nfunction tableOf(values) {\n  const rows = values || [];\n  const header = rows.length && rows[0][0] === 'id';\n  return { header, rows: header ? rows.slice(1) : [] };\n}\nconst cell = (row, c) => row[TCOLS.indexOf(c)] || '';\nconst rowObject = (row) => Object.fromEntries(TCOLS.map((c) => [c, cell(row, c)]));\nconst msg = $('Normalize').first().json;\nconst tickets = tableOf($input.first().json.values);\nconst now = nowMs();\nconst iso = new Date(now).toISOString();\nconst ticketId = msg.callback.ticket;\nconst index = tickets.rows.findIndex((r) => cell(r, 'id') === ticketId);\nconst done = (note) => [{ json: { found: index >= 0, deliver: false, write: false, note, callback_id: msg.callback.id || '', team_chat: cfg.team_chat_id, message_id: msg.callback.message_id || '' } }];\nif (index < 0) return done('Обращение не найдено в таблице');\nconst row = rowObject(tickets.rows[index]);\nconst sheetRow = index + (tickets.header ? 2 : 1);\n\nif (msg.kind === 'dismiss') {\n  row.status = 'new'; row.updated_at = iso; row.draft = '';\n  return [{ json: { found: true, deliver: false, write: true, note: `Черновик отклонён${msg.callback.by ? ': ' + msg.callback.by : ''}. Ответьте клиенту сами.`,\n    http: { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(sheetRow))) + '?valueInputOption=RAW', body: { values: [TCOLS.map((c) => String(row[c] || ''))] } },\n    callback_id: msg.callback.id, team_chat: cfg.team_chat_id, message_id: msg.callback.message_id } }];\n}\nif (['answered', 'closed'].includes(row.status) && msg.kind === 'approve') return done('Это обращение уже отвечено');\n\nconst text = msg.kind === 'approve' ? row.draft : msg.text;\nif (!text) return done('Черновика нет — ответьте сами ответом на сообщение бота');\nconst who = msg.callback.by || 'команда';\nrow.status = 'answered'; row.updated_at = iso; row.draft = '';\nif (!row.first_response_at) row.first_response_at = iso;\nif (!row.assignee) row.assignee = who;\nrow.history = `${row.history ? row.history + '\\n' : ''}${localText(now)} · ${who}: ${text.replace(/\\n+/g, ' ').slice(0, 300)}`.slice(-4000);\nconst subject = row.subject ? (/^re:/i.test(row.subject) ? row.subject : 'Re: ' + row.subject) : ((cfg.email || {}).default_subject || 'Ответ службы поддержки');\n// Answer where the customer can read it: Telegram if they wrote there, otherwise email.\nconst via = row.telegram_chat ? 'telegram' : row.email ? 'email' : '';\nif (!via) return done('У обращения нет ни почты, ни Telegram — ответить некуда');\nreturn [{ json: {\n  found: true, deliver: true, write: true, via, reply_text: text, reply_email: row.email, reply_subject: subject, reply_chat: row.telegram_chat,\n  note: `Отправлено клиенту (${who})`,\n  http: { method: 'PUT', url: sheetUrl(encodeURIComponent(rowRange(sheetRow))) + '?valueInputOption=RAW', body: { values: [TCOLS.map((c) => String(row[c] || ''))] } },\n  callback_id: msg.callback.id || '', team_chat: cfg.team_chat_id, message_id: msg.callback.message_id || '',\n} }];\n"
      },
