t({ act: true, write: true, callback_id: callbackId, note, http: batchUpdate([botWrite(found.sheetRow, post)]) });\nconst at = whenOf(post.publish_at);\nconst when = at ? `в ${stamp(at)}` : 'в ближайшие минуты';\nif (action === 'ok') {\n  if (!post.draft && !post.final) return out({ act: true, callback_id: callbackId, note: 'Черновика ещё нет' });\n  post.status = 'approved'; post.final = post.final || post.draft; post.approved_by = who;\n  return write(`${who || 'Команда'} одобрил(а) «${post.topic}». Публикация ${when}.`);\n}\nif (action === 'edit') {\n  post.status = 'approved'; post.final = text.slice(0, 20000); post.approved_by = who;\n  return write(`Текст «${post.topic}» заменён и одобрен (${who}). Публикация ${when}.`);\n}\nif (action === 'redo') {\n  post.status = 'idea'; post.attempts = 0; post.error = '';\n  post.notes = text ? text.slice(0, 1000) : post.notes;\n  return write(`«${post.topic}» — пишу новый вариант${text ? ' с учётом замечания' : ''}.`);\n}\npost.status = 'skipped';\nreturn write(`«${post.topic}» пропущена.`);\n"
