const ch = cfg.channels[post.channel] || {};
const parsed = parseModelJson($input.first().json);
const text = parsed.data ? String(parsed.data.text || '').trim() : '';
let problem = parsed.problem || (!text ? 'пустой текст' : text.length > (ch.max_chars || 2000) ? `текст длиннее ${ch.max_chars || 2000} знаков` : '');
const data = pick.needs_id ? [{ range: `${quoteSheet(cfg.plan_sheet)}!A${pick.sheet_row}`, values: [[post.id]] }] : [];
