        "jsCode": "// Record Result — after the channel answered: published with a link, or failed with the reason. The team hears about both.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Plan sheet: one row per post. Columns A–G are the team's; H–Q are kept by the workflows (notes holds the editor's rewrite request).\nconst PCOLS = ['id', 'publish_at', 'channel', 'topic', 'brief', 'pillar', 'image_url', 'status', 'title', 'draft', 'final', 'attempts', 'approved_by',\n  'published_at', 'link', 'error', 'notes'];\nconst BOT_FROM = PCOLS.indexOf('status');\nconst BOT_TO = PCOLS.indexOf('notes');\nconst colLetter = (index) => String.fromCharCode(65 + index);\nconst planRange = () => `${quoteSheet(cfg.plan_sheet)}!A1:${colLetter(PCOLS.length - 1)}`;\n// Unformatted values: dates come back as serial numbers whatever the spreadsheet's locale is.\nconst planReadUrl = () => sheetUrl(encodeURIComponent(planRange())) + '?valueRenderOption=UNFORMATTED_VALUE&dateTimeRenderOption=SERIAL_NUMBER';\nfunction planTable(values) {\n  const all = values || [];\n  const header = all.length > 0 && String(all[0][0]).trim().toLowerCase() === 'id';\n  return { header, rows: (header ? all.slice(1) : all).map((r, i) => ({ sheetRow: i + (header ? 2 : 1), post: planObject(r) })) };\n}\nfunction planObject(row) {\n  const o = {};\n  PCOLS.forEach((c, i) => { const v = row[i]; o[c] = v === undefined || v === null ? '' : (c === 'publish_at' && typeof v === 'number' ? v : String(v).trim()); });\n  o.status = o.status.toLowerCase() || (o.topic ? 'idea' : '');\n  o.attempts = Number(o.attempts) || 0;\n  return o;\n}\n// The workflows write H–Q in one range, so the team's columns are never touched.\nfunction botWrite(sheetRow, post) {\n  return { range: `${quoteSheet(cfg.plan_sheet)}!${colLetter(BOT_FROM)}${sheetRow}:${colLetter(BOT_TO)}${sheetRow}`, values: [PCOLS.slice(BOT_FROM, BOT_TO + 1).map((c) => String(post[c] === undefined ? '' : post[c]))] };\n}\nconst batchUpdate = (data) => ({ method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data } });\nfunction localToMs(y, mo, d, h, mi) {\n  const want = Date.UTC(y, mo - 1, d, h, mi);\n  let guess = want;\n  for (let i = 0; i < 3; i++) {\n    const p = localParts(guess);\n    guess += want - Date.UTC(Number(p.date.slice(0, 4)), Number(p.date.slice(5, 7)) - 1, Number(p.date.slice(8, 10)), p.hour, p.minute);\n  }\n  return guess;\n}\n// publish_at: a date cell (serial number), \"2026-10-28 10:00\" or \"28.10.2026 10:00\", in the Config time zone. Empty means \"as soon as possible\".\nfunction whenOf(value) {\n  if (value === '' || value === null || value === undefined) return null;\n  if (typeof value === 'number' || /^\\d+(\\.\\d+)?$/.test(String(value))) {\n    const wall = new Date(Math.round((Number(value) - 25569) * 86400000));\n    return localToMs(wall.getUTCFullYear(), wall.getUTCMonth() + 1, wall.getUTCDate(), wall.getUTCHours(), wall.getUTCMinutes());\n  }\n  const s = String(value).trim();\n  let m = /^(\\d{4})-(\\d{1,2})-(\\d{1,2})(?:[ T](\\d{1,2}):(\\d{2}))?/.exec(s);\n  if (m) return localToMs(+m[1], +m[2], +m[3], +(m[4] || 9), +(m[5] || 0));\n  m = /^(\\d{1,2})[./](\\d{1,2})[./](\\d{4})(?:,?\\s+(\\d{1,2}):(\\d{2}))?/.exec(s);\n  if (m) return localToMs(+m[3], +m[2], +m[1], +(m[4] || 9), +(m[5] || 0));\n  return NaN;\n}\nconst pad = (n) => String(n).padStart(2, '0');\nconst stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };\nfunction parseModelJson(input) {\n  const content = input && input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content;\n  if (!content) return { problem: input && input.error ? 'llm_error' : 'no_answer' };\n  try { const t = String(content).replace(/```(json)?/g, ''); return { data: JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)) }; } catch (e) { return { problem: 'bad_json' }; }\n}\nconst llmBase = (messages) => ({ model: (cfg.llm || {}).model, temperature: (cfg.llm || {}).temperature === undefined ? 0.7 : cfg.llm.temperature,\n  ...((cfg.llm || {}).json_mode ? { response_format: { type: 'json_object' } } : {}), messages });\nfunction brandLines() {\n  const b = cfg.brand || {};\n  return [`Бренд: ${b.name || ''}. ${b.about || ''}`, `Аудитория: ${b.audience || ''}`, `Голос: ${b.voice || ''}`,\n    ...(b.rules || []).map((r) => `- ${r}`)].join('\\n');\n}\nconst due = $('Pick Due').first().json;\nconst res = $input.first().json || {};\nconst ch = cfg.channels[due.channel] || {};\nconst post = Object.assign({}, due.post);\nconst failed = Boolean(res.error);\nif (failed) {\n  const e = res.error;\n  post.status = 'failed';\n  post.error = String((e && (e.description || e.message)) || JSON.stringify(e)).slice(0, 300);\n} else {\n  const msgId = (res.result || res).message_id;\n  post.status = 'published';\n  post.published_at = stamp(nowMs());\n  post.error = '';\n  post.link = due.kind === 'telegram' ? (ch.link_base && msgId ? `${String(ch.link_base).replace(/\\/$/, '')}/${msgId}` : '') : String(res.link || res.url || '');\n}\nreturn [{ json: {\n  http: batchUpdate([botWrite(due.sheet_row, post)]), chat: cfg.approval_chat_id,\n  notify: failed || cfg.notify_published !== false,\n  text: failed ? `Не опубликовано: «${post.topic}» (${post.channel})\\nОшибка: ${post.error}\\nИсправьте и поставьте статус approved — бот попробует снова.`\n    : `Опубликовано: «${post.topic}» (${post.channel})${post.link ? '\\n' + post.link : ''}`,\n} }];\n"
