        "jsCode": "// Config — настройки. Меняйте значения справа от двоеточия.\nreturn [{ json: {\n  \"timezone\": \"Europe/Kyiv\",\n  \"locale\": \"ru-RU\",\n  \"sheets_api_base\": \"https://sheets.googleapis.com/v4\",\n  \"spreadsheet_id\": \"REPLACE_WITH_SPREADSHEET_ID\",\n  \"deals_sheet\": \"Deals\",\n  \"team_chat_id\": \"REPLACE_WITH_TEAM_CHAT_ID\",\n  \"currency\": \"€\",\n  \"owners\": [\n    {\n      \"name\": \"REPLACE: Имя менеджера 1\",\n      \"chat_id\": \"REPLACE_WITH_CHAT_ID\",\n      \"active\": true\n    },\n    {\n      \"name\": \"REPLACE: Имя менеджера 2\",\n      \"chat_id\": \"REPLACE_WITH_CHAT_ID\",\n      \"active\": true\n    }\n  ],\n  \"stages\": [\n    {\n      \"id\": \"new\",\n      \"label\": \"Новая\",\n      \"stale_days\": 1\n    },\n    {\n      \"id\": \"contacted\",\n      \"label\": \"Связались\",\n      \"next_action\": \"Назначить встречу или звонок\",\n      \"follow_up_days\": 2,\n      \"stale_days\": 3\n    },\n    {\n      \"id\": \"meeting\",\n      \"label\": \"Встреча\",\n      \"next_action\": \"Отправить предложение\",\n      \"follow_up_days\": 1,\n      \"stale_days\": 5\n    },\n    {\n      \"id\": \"proposal\",\n      \"label\": \"КП отправлено\",\n      \"next_action\": \"Узнать решение\",\n      \"follow_up_days\": 3,\n      \"stale_days\": 4\n    },\n    {\n      \"id\": \"won\",\n      \"label\": \"Выиграна\"\n    },\n    {\n      \"id\": \"lost\",\n      \"label\": \"Проиграна\"\n    }\n  ],\n  \"escalate_after_minutes\": 120,\n  \"working_hours\": {\n    \"mon\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"tue\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"wed\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"thu\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"fri\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    }\n  }\n} }];\n"
