      "id": "a69f1ddd-78f8-51f1-9ac8-41aa994d867b",
      "name": "Read Deals",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        -80,
        0
      ],
      "credentials": {
        "googleSheetsOAuth2Api": {
          "id": "REPLACE_ME",
