    {
      "parameters": {
        "jsCode": "// Config — настройки. Меняйте значения справа от двоеточия.\nreturn [{ json: {\n  \"timezone\": \"Europe/Kyiv\",\n  \"locale\": \"ru-RU\",\n  \"sheets_api_base\": \"https://sheets.googleapis.com/v4\",\n  \"spreadsheet_id\": \"REPLACE_WITH_SPREADSHEET_ID\",\n  \"sheet_name\": \"Leads\",\n  \"notify_chat_id\": \"REPLACE_WITH_CHAT_ID\",\n  \"hot_chat_id\": \"\",\n  \"working_hours\": {\n    \"mon\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"tue\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"wed\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"thu\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"fri\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    }\n  },\n  \"sla\": {\n    \"first_reminder_minutes\": 15,\n    \"escalate_minutes\": 60,\n    \"escalate_chat_id\": \"\"\n  }\n} }];\n"
      },
      "id": "26086f0c-1e0c-5f71-868b-595923c87ab3",
      "name": "Config",
      "type": "n8n-nodes-base.code",
