    {
      "parameters": {
        "jsCode": "// Find Overdue — leads nobody has taken. Status stays \"new\" until a manager changes it in the sheet.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Column order of the Leads sheet. The sheet may start empty: the header is written with the first lead.\nconst COLUMNS = ['id', 'created_at', 'source', 'form', 'name', 'phone', 'email', 'message', 'utm_source', 'utm_medium', 'utm_campaign', 'page',\n  'score', 'intent', 'summary', 'status', 'owner', 'touches', 'last_touch_at', 'reminded_level', 'notes'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst LAST = colLetter(COLUMNS.length - 1);\nconst rows = $input.first().json.values || [];\nconst now = nowMs();\nconst sla = cfg.sla || {};\nconst here = localParts(now);\nconst day = (cfg.working_hours || {})[here.weekday];\nconst minutes = here.hour * 60 + here.minute;\nconst toMin = (t) => { const [h, m] = t.split(':').map(Number); return h * 60 + m; };\n// Outside working hours nobody can act on a reminder, so none is sent; overdue leads come up in the morning.\nif (!day || minutes < toMin(day.open) || minutes >= toMin(day.close)) return [{ json: { send: false, reason: 'outside_hours' } }];\nif (!rows.length || rows[0][0] !== 'id') return [{ json: { send: false, reason: 'empty_sheet' } }];\n\nconst at = (row, c) => row[COLUMNS.indexOf(c)] || '';\nconst levelCol = colLetter(COLUMNS.indexOf('reminded_level'));\nconst first = [], second = [], updates = [];\nrows.slice(1).forEach((row, i) => {\n  if (at(row, 'status') !== 'new') return;\n  const since = Date.parse(at(row, 'last_touch_at') || at(row, 'created_at'));\n  if (isNaN(since)) return;\n  const waited = Math.round((now - since) / MIN);\n  const level = Number(at(row, 'reminded_level') || 0);\n  const entry = { id: at(row, 'id'), name: at(row, 'name') || '—', contact: at(row, 'phone') || at(row, 'email'), score: at(row, 'score'), waited, owner: at(row, 'owner') };\n  if (waited >= (sla.escalate_minutes || 60) && level < 2) { second.push(entry); updates.push({ range: `${quoteSheet(cfg.sheet_name)}!${levelCol}${i + 2}`, values: [['2']] }); }\n  else if (waited >= (sla.first_reminder_minutes || 15) && level < 1) { first.push(entry); updates.push({ range: `${quoteSheet(cfg.sheet_name)}!${levelCol}${i + 2}`, values: [['1']] }); }\n});\nif (!updates.length) return [{ json: { send: false, reason: 'nothing_overdue' } }];\n\nconst fmt = (e) => `• ${e.name}, ${e.contact}, ${e.score}/5 — ждёт ${e.waited >= 120 ? Math.round(e.waited / 60) + ' ч' : e.waited + ' мин'}${e.owner ? ', ' + e.owner : ''} (${e.id})`;\nconst messages = [];\nif (first.length) messages.push({ chat_id: cfg.notify_chat_id, text: [`Заявки без ответа: ${first.length}`, ...first.map(fmt), 'Поменяйте статус в таблице, когда свяжетесь.'].join('\\n') });\nif (second.length) messages.push({ chat_id: sla.escalate_chat_id || cfg.hot_chat_id || cfg.notify_chat_id, text: [`Заявки без ответа больше ${sla.escalate_minutes || 60} мин: ${second.length}`, ...second.map(fmt)].join('\\n') });\nreturn messages.map((m, i) => ({ json: Object.assign({ send: true }, m, i === 0 ? { http: { method: 'POST', url: `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchUpdate`, body: { valueInputOption: 'RAW', data: updates } } } : {}) }));\n"
      },
