      ]
    },
    {
      "parameters": {
        "jsCode": "// Tool Failed — the calendar did not answer or refused. Never invent a result.
const failure = $input.first().json || {};
let ctx = {};
try { ctx = $('Decide').first().json; } catch (e) { ctx = $('Plan').first().json; }
const text = JSON.stringify(failure.error || failure).slice(0, 600);
const status = Number((failure.error && (failure.error.httpCode || failure.error.status)) || failure.statusCode || 0);
// A repeated create with the same id means the first attempt went through.
if (ctx.tool === 'create_booking' && ctx.needs_write && (status === 409 || /\b409\b|already exists|duplicate/i.test(text))) {
  return [{ json: Object.assign({}, ctx, { result: ctx.on_success, needs_notify: false }) }];
}
return [{ json: Object.assign({}, ctx, { needs_notify: true,
  staff_message: ['Сбой инструмента голосового агента', `Инструмент: ${ctx.tool}`, `Звонок: ${ctx.call_id || '—'}`, text].join('\n'),
  result: { ok: false, error: 'tool_unavailable', say: 'Система записи сейчас недоступна. Извинитесь, не называйте результат, предложите оставить заявку через request_callback или перевести на администратора.' } }) }];
"
