      "headers": {
        "X-Voice-Secret": "REPLACE_WITH_SECRET"
      },
      "parameters": {
        "type": "object",
        "properties": {
          "service_id": {
            "type": "string",
            "description": "Идентификатор услуги из каталога."
          },
          "slot_start": {
            "type": "string",
            "description": "Значение slot_start из ответа check_availability, без изменений."
