      say: 'Эта запись уже создана. Подтвердите клиенту услугу, дату и время.' });
  }
  const problem = slotError(start, ctx.service, a.staff_id);
  if (problem) {
    const other = nearest(dayStart(localDate(start)), ctx.service, a.staff_id, 'any', null, 8);
    const why = { too_soon: 'Это время слишком близко или уже прошло.', outside_hours: 'В это время мы не работаем.', off_grid: 'На это время записать нельзя.', slot_taken: 'Это время только что заняли.' }[problem];
    return done({ ok: false, error: problem, slots: other, say: why + ' Извинитесь и предложите варианты из slots.' });
  }
  const end = start + ctx.service.duration_min * MIN;
  const staffId = freeStaff(start, end, ctx.service, a.staff_id)[0];
  const details = {};
  for (const key of cfg.detail_fields || []) if (a[key]) details[key] = String(a[key]).slice(0, 300);
  const lines = [`Клиент: ${a.customer_name}`, `Телефон: ${a.customer_phone}`, `Услуга: ${ctx.service.name}`, staffId ? `Специалист: ${staffName(staffId)}` : '']
    .concat(Object.keys(details).map((k) => `${(cfg.detail_labels || {})[k] || k}: ${details[k]}`))
    .concat(a.notes ? [`Комментарий: ${String(a.notes).slice(0, 300)}`] : [], ['Источник: голосовой агент']).filter(Boolean);
  return write({ method: 'POST', url: `${cfg.calendar_api_base}/calendars/${encodeURIComponent(cfg.calendar_id)}/events`, body: {
    id, summary: `${ctx.service.name} — ${a.customer_name}`, description: lines.join('\n'),
    start: { dateTime: new Date(start).toISOString(), timeZone: TZ }, end: { dateTime: new Date(end).toISOString(), timeZone: TZ },
    extendedProperties: { private: Object.assign({ phone: a.customer_phone, service_id: a.service_id, staff_id: staffId || '', source: 'voice-agent', call_id: ctx.call_id || '' }, details) },
  } }, { ok: true, booking_id: id, service: ctx.service.name, price: ctx.service.price, slot_start: localIso(start), spoken: spoken(start), staff: staffName(staffId),
    say: 'Запись создана. Подтвердите клиенту услугу, дату и время' + (cfg.address ? ' и назовите адрес: ' + cfg.address : '') + '.' },
  ['Новая запись', spoken(start)].concat(lines).join('\n'));
}

if (ctx.tool === 'find_booking') {
  const mine = busy.filter((event) => event.phone === a.customer_phone && event.end > now).slice(0, 5).map(describe);
  return done({ ok: true, bookings: mine, say: mine.length ? 'Назовите клиенту найденные записи и уточните, о какой речь.' : 'На этот номер предстоящих записей нет. Уточните номер, на который записывались.' });
}

const booking = busy.find((event) => event.id === a.booking_id);
if (!booking || booking.phone !== a.customer_phone) {
  return done({ ok: false, error: 'booking_not_found', say: 'Запись с таким номером на этот телефон не найдена. Вызовите find_booking и уточните.' });
}
const eventUrl = `${cfg.calendar_api_base}/calendars/${encodeURIComponent(cfg.calendar_id)}/events/${encodeURIComponent(booking.id)}`;
const info = describe(booking);
const hoursLeft = (booking.start - now) / (60 * MIN);

if (ctx.tool === 'cancel_booking') {
  const late = cfg.cancel_min_hours && hoursLeft < cfg.cancel_min_hours;
  return write({ method: 'PATCH', url: eventUrl, body: { status: 'cancelled' } },
    { ok: true, cancelled: info, late_cancellation: Boolean(late), say: 'Запись отменена. Подтвердите это клиенту' + (late && cfg.late_cancel_note ? '. ' + cfg.late_cancel_note : '') + ' и предложите записаться на другое время.' },
    ['Отмена записи', info.spoken, `Клиент: ${a.customer_phone}`, info.service, a.reason ? `Причина: ${a.reason}` : ''].filter(Boolean).join('\n'));
}

// reschedule_booking
const service = serviceOf(info.service_id) || { duration_min: Math.round((booking.end - booking.start) / MIN), name: info.service };
const start = parseSlot(a.new_slot_start);
const wanted = a.staff_id || booking.staff || undefined;
let problem = isNaN(start) ? 'bad_slot' : slotError(start, service, wanted, booking.id);
let staffId = problem ? null : freeStaff(start, start + service.duration_min * MIN, service, wanted, booking.id)[0];
if (problem === 'slot_taken' && wanted && !a.staff_id) {
  // The same specialist is busy; another one may be free.
  if (!slotError(start, service, undefined, booking.id)) { problem = null; staffId = freeStaff(start, start + service.duration_min * MIN, service, undefined, booking.id)[0]; }
}
if (problem) {
  const other = isNaN(start) ? [] : nearest(dayStart(localDate(start)), service, undefined, 'any', booking.id, 8);
  return done({ ok: false, error: problem, slots: other, say: 'На это время перенести нельзя. Предложите варианты из slots. Прежняя запись сохранена.' });
}
const end = start + service.duration_min * MIN;
return write({ method: 'PATCH', url: eventUrl, body: {
  start: { dateTime: new Date(start).toISOString(), timeZone: TZ }, end: { dateTime: new Date(end).toISOString(), timeZone: TZ },
  extendedProperties: { private: { staff_id: staffId || '' } },
} }, { ok: true, booking_id: booking.id, service: service.name, slot_start: localIso(start), spoken: spoken(start), staff: staffName(staffId), previous: info.spoken,
  say: 'Запись перенесена. Назовите клиенту новые дату и время.' },
['Перенос записи', `Было: ${info.spoken}`, `Стало: ${spoken(start)}`, `Клиент: ${a.customer_phone}`, service.name].join('\n'));
"
