        "jsCode": "// Normalise the end-of-call report of any of the three providers into one message.\nconst cfg = $('Config').first().json;\nconst body = $('Call Ended Webhook').first().json.body || {};\nconst pick = (...values) => values.find((value) => value !== undefined && value !== null && value !== '');\nlet provider = 'unknown', summary, seconds, caller, reason, success, callId;\n\nif (body.message && body.message.type === 'end-of-call-report') {\n  const m = body.message;\n  provider = 'vapi';\n  summary = pick(m.summary, m.analysis && m.analysis.summary);\n  seconds = pick(m.durationSeconds, m.call && m.call.durationSeconds);\n  caller = m.call && m.call.customer && m.call.customer.number;\n  reason = m.endedReason;\n  success = m.analysis && m.analysis.successEvaluation;\n  callId = m.call && m.call.id;\n} else if (body.event && body.call) {\n  if (body.event !== 'call_analyzed') return [];\n  const c = body.call;\n  provider = 'retell';\n  summary = c.call_analysis && c.call_analysis.call_summary;\n  seconds = c.duration_ms ? Math.round(c.duration_ms / 1000) : undefined;\n  caller = c.direction === 'outbound' ? c.to_number : c.from_number;\n  reason = c.disconnection_reason;\n  success = c.call_analysis && c.call_analysis.call_successful;\n  callId = c.call_id;\n} else if (body.type && body.data) {\n  if (body.type !== 'post_call_transcription') return [];\n  const d = body.data;\n  provider = 'elevenlabs';\n  summary = d.analysis && d.analysis.transcript_summary;\n  seconds = d.metadata && d.metadata.call_duration_secs;\n  caller = d.metadata && d.metadata.phone_call && d.metadata.phone_call.external_number;\n  reason = d.metadata && d.metadata.termination_reason;\n  success = d.analysis && d.analysis.call_successful;\n  callId = d.conversation_id;\n} else {\n  return [];\n}\n\nconst minutes = seconds ? `${Math.floor(seconds / 60)}:${String(Math.round(seconds % 60)).padStart(2, '0')}` : '—';\nconst lines = [\n  'Звонок завершён',\n  `Номер: ${caller || 'не определён'}`,\n  `Длительность: ${minutes}`,\n  success !== undefined ? `Цель достигнута: ${success === true || success === 'true' || success === 'successful' ? 'да' : String(success)}` : '',\n  reason ? `Завершение: ${reason}` : '',\n  '',\n  summary ? String(summary).slice(0, 900) : 'Сводка не пришла — проверьте, что у провайдера включён анализ звонка.',\n].filter((line) => line !== '');\nreturn [{ json: { provider, call_id: callId || '', staff_message: lines.join('\\n'), chat_id: cfg.staff_chat_id } }];\n"
