          "id": "REPLACE_ME",
          "name": "WhatsApp App Secret"
        }
      },
      "notes": "Секрет приложения Meta: App settings → Basic → App secret."
    },
    {
      "parameters": {
        "jsCode": "// Config — настройки. Меняйте значения справа от двоеточия.\nreturn [{ json: {\n  \"timezone\": \"Europe/Kyiv\",\n  \"locale\": \"ru-RU\",\n  \"sheets_api_base\": \"https://sheets.googleapis.com/v4\",\n  \"spreadsheet_id\": \"REPLACE_WITH_SPREADSHEET_ID\",\n  \"contacts_sheet\": \"Contacts\",\n  \"catalog_sheet\": \"Catalog\",\n  \"catalog_max_chars\": 8000,\n  \"graph_api_base\": \"https://graph.facebook.com/v25.0\",\n  \"phone_number_id\": \"REPLACE_WITH_PHONE_NUMBER_ID\",\n  \"verify_token\": \"REPLACE_WITH_RANDOM_TOKEN\",\n  \"verify_signature\": true,\n  \"max_message_age_minutes\": 60,\n  \"team_chat_id\": \"REPLACE_WITH_TEAM_CHAT_ID\",\n  \"handoff_hours\": 12,\n  \"llm\": {\n    \"enabled\": true,\n    \"base_url\": \"https://api.openai.com/v1\",\n    \"model\": \"REPLACE_WITH_MODEL\",\n    \"json_mode\": true\n  },\n  \"business\": {\n    \"name\": \"REPLACE: название\",\n    \"description\": \"REPLACE: чем занимается компания, одной фразой\",\n    \"offer\": \"REPLACE: что продаёте и кому\",\n    \"next_step\": \"REPLACE: что предлагаем готовому клиенту — звонок, замер, запись\",\n    \"tone\": \"дружелюбно, коротко, на «вы», без канцелярита\"\n  },\n  \"qualify\": [\n    {\n      \"key\": \"need\",\n      \"label\": \"Что нужно клиенту\"\n    },\n    {\n      \"key\": \"budget\",\n      \"label\": \"Бюджет\"\n    },\n    {\n      \"key\": \"timeline\",\n      \"label\": \"Когда нужно\"\n    }\n  ],\n  \"opt_out_words\": [\n    \"стоп\",\n    \"stop\",\n    \"отписаться\",\n    \"unsubscribe\"\n  ],\n  \"opt_in_words\": [\n    \"старт\",\n    \"start\"\n  ],\n  \"human_words\": [\n    \"менеджер\",\n    \"оператор\",\n    \"человек\",\n    \"живой\",\n    \"позвоните\"\n  ],\n  \"texts\": {\n    \"opt_out\": \"Вы отписались от сообщений. Чтобы вернуться, напишите «старт».\",\n    \"opt_in\": \"Снова на связи! Чем можем помочь?\",\n    \"handoff\": \"Передаю ваш вопрос менеджеру — он ответит здесь же в рабочее время.\",\n    \"fallback\": \"Спасибо за сообщение! Менеджер ответит здесь же в рабочее время.\"\n  },\n  \"followup\": {\n    \"enabled\": true,\n    \"after_hours\": 20,\n    \"text\": \"{name}, подскажите, вопрос ещё актуален? Если удобно, продолжим здесь.\"\n  },\n  \"working_hours\": {\n    \"mon\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"tue\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"wed\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"thu\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"fri\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    },\n    \"sat\": {\n      \"open\": \"09:00\",\n      \"close\": \"19:00\"\n    }\n  },\n  \"max_reply_chars\": 700,\n  \"report_chat_id\": \"\"\n} }];\n"
      },
      "id": "1e766447-fa61-5c39-8c85-1c4b38ddc7f8",
      "name": "Config",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        -460,
        -60
      ],
      "notes": "Единственный узел, который нужно редактировать."
    },
    {
      "parameters": {
        "conditions": {
          "boolean": [
            {
              "value1": "={{ $('Verify Webhook').isExecuted }}",
              "value2": true
            }
          ]
        }
      },
      "id": "9929b8c4-5051-51d9-a8da-05bcabba5626",
      "name": "Verification?",
      "type": "n8n-nodes-base.if",
      "typeVersion": 1,
      "position": [
        -260,
        -60
      ]
    },
    {
      "parameters": {
        "jsCode": "// Verify Webhook — Meta's one-time check when the webhook URL is saved in the app settings.\nconst cfg = $('Config').first().json;\nconst query = $('Verify Webhook').first().json.query || {};\nconst ok = query['hub.mode'] === 'subscribe' && cfg.verify_token && !String(cfg.verify_token).startsWith('REPLACE') && query['hub.verify_token'] === cfg.verify_token;\nreturn [{ json: { ok, status: ok ? 200 : 403, body: ok ? String(query['hub.challenge'] || '') : 'forbidden' } }];\n"
      },
      "id": "e8499198-7c1a-5afe-985b-54be33bc4afd",
      "name": "Verify",
      "type": "n8n-nodes-base.code",
      "typeVersion": 2,
      "position": [
        -40,
        -200
      ]
    },
    {
      "parameters": {
        "respondWith": "text",
        "responseBody": "={{ $json.body }}",
        "options": {
          "responseCode": "={{ $json.status }}"
        }
      },
      "id": "40317563-961a-5b2c-88d5-30d63d11f11d",
      "name": "Respond Verify",
      "type": "n8n-nodes-base.respondToWebhook",
      "typeVersion": 1.1,
      "position": [
        180,
        -200
      ]
    },
    {
      "parameters": {
        "jsCode": "// Inbound — checks Meta's signature and turns the webhook into one message, or says why it is skipped.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Contacts sheet: one row per WhatsApp number. The sheet may start empty: the header is written with the first contact.\nconst CCOLS = ['wa_id', 'name', 'phone', 'first_seen', 'last_in_at', 'last_out_at', 'status', 'stage', 'need', 'budget', 'timeline', 'details',\n  'hot', 'handoff_until', 'followup_sent', 'history', 'manager', 'notes'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst CLAST = colLetter(CCOLS.length - 1);\nconst contactsRange = () => `${quoteSheet(cfg.contacts_sheet)}!A1:${CLAST}`;\nconst contactRow = (row) => `${quoteSheet(cfg.contacts_sheet)}!A${row}:${CLAST}${row}`;\nconst waBatchUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(contactsRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.catalog_sheet)}!A1:C`)}`;\nconst contactsTable = (values) => { const rows = values || []; const header = rows.length && rows[0][0] === 'wa_id'; return { header, rows: header ? rows.slice(1) : [] }; };\nconst ccell = (row, c) => row[CCOLS.indexOf(c)] || '';\nconst contactObject = (row) => Object.fromEntries(CCOLS.map((c) => [c, ccell(row, c)]));\nconst graphUrl = () => `${cfg.graph_api_base}/${encodeURIComponent(cfg.phone_number_id)}/messages`;\nconst waText = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: String(body).slice(0, 4000) } });\nconst signed = $('Sign Body').first().json;\nconst body = signed.body || {};\nconst header = String((signed.headers || {})['x-hub-signature-256'] || '');\nconst skip = (kind, extra) => [{ json: Object.assign({ kind, batch_url: waBatchUrl() }, extra || {}) }];\n\n// The body is signed with the app secret; anything else posting to this address is refused.\nif (cfg.verify_signature !== false) {\n  const expected = 'sha256=' + String(signed.signature_expected || '');\n  if (!header || header.length !=