        "jsCode": "// Reply — turns the decision into the WhatsApp message, the sheet write and, when needed, the note to the managers.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Contacts sheet: one row per WhatsApp number. The sheet may start empty: the header is written with the first contact.\nconst CCOLS = ['wa_id', 'name', 'phone', 'first_seen', 'last_in_at', 'last_out_at', 'status', 'stage', 'need', 'budget', 'timeline', 'details',\n  'hot', 'handoff_until', 'followup_sent', 'history', 'manager', 'notes'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst CLAST = colLetter(CCOLS.length - 1);\nconst contactsRange = () => `${quoteSheet(cfg.contacts_sheet)}!A1:${CLAST}`;\nconst contactRow = (row) => `${quoteSheet(cfg.contacts_sheet)}!A${row}:${CLAST}${row}`;\nconst waBatchUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(contactsRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.catalog_sheet)}!A1:C`)}`;\nconst contactsTable = (values) => { const rows = values || []; const header = rows.length && rows[0][0] === 'wa_id'; return { header, rows: header ? rows.slice(1) : [] }; };\nconst ccell = (row, c) => row[CCOLS.indexOf(c)] || '';\nconst contactObject = (row) => Object.fromEntries(CCOLS.map((c) => [c, ccell(row, c)]));\nconst graphUrl = () => `${cfg.graph_api_base}/${encodeURIComponent(cfg.phone_number_id)}/messages`;\nconst waText = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: String(body).slice(0, 4000) } });\nconst ctx = $('Converse').first().json;\nconst msg = $('Inbound').first().json;\nconst input = $input.first().json || {};\nconst now = nowMs();\nconst iso = new Date(now).toISOString();\nconst contact = Object.assign({}, ctx.contact);\nconst STAGES = ['new', 'qualifying', 'qualified', 'hot', 'not_fit', 'support'];\nlet route = ctx.route;\nlet reply = ctx.reply || '';\nlet buttons = [];\nlet reason = ctx.reason || '';\nlet summary = '';\nlet problem = '';\n\nif (route === 'ai') {\n  const content = input.choices && input.choices[0] && input.choices[0].message && input.choices[0].message.content;\n  let p = null;\n  if (content) { try { const t = String(content).replace(/```(json)?/g, ''); p = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)); } catch (e) { problem = 'bad_json'; } }\n  else problem = input.error ? 'llm_error' : 'no_answer';\n  if (p && String(p.reply || '').trim()) {\n    reply = String(p.reply).trim().slice(0, cfg.max_reply_chars || 700);\n    for (const q of cfg.qualify || []) {\n      const v = p.fields && p.fields[q.key];\n      if (v && String(v).trim()) contact[q.key] = String(v).trim().slice(0, 200);\n    }\n    if (STAGES.includes(p.stage)) contact.stage = p.stage;\n    buttons = Array.isArray(p.buttons) ? p.buttons.map((b) => String(b).trim().slice(0, 20)).filter(Boolean).slice(0, 3) : [];\n    summary = String(p.summary || '').slice(0, 300);\n    const hot = p.hot === true || contact.stage === 'hot';\n    if (hot && contact.hot !== 'yes') { contact.hot = 'yes'; route = 'hot'; reason = 'клиент готов к следующему шагу'; }\n    else if (p.handoff === true) { route = 'handoff'; reason = String(p.handoff_reason || 'нужен человек').slice(0, 200); }\n  } else {\n    // Without a model answer the client is not left in silence: a person takes over.\n    route = 'handoff'; reason = 'модель не ответила'; reply = cfg.texts.fallback; problem = problem || 'empty';\n  }\n}\nif (route === 'handoff' || route === 'hot') {\n  contact.status = 'manager';\n  contact.handoff_until = new Date(now + (cfg.handoff_hours || 12) * 60 * MIN).toISOString();\n  if (route === 'handoff' && !reply) reply = cfg.texts.handoff;\n}\nif (reply) {\n  contact.last_out_at = iso;\n  contact.history = `${contact.history}\\n${localText(now)} · бот: ${reply.replace(/\\n+/g, ' ').slice(0, 400)}`.slice(-3500);\n}\nconst message = !reply ? null : buttons.length && route === 'ai'\n  ? { messaging_product: 'whatsapp', recipient_type: 'individual', to: msg.wa_id, type: 'interactive',\n      interactive: { type: 'button', body: { text: reply.slice(0, 1024) }, action: { buttons: buttons.map((title, i) => ({ type: 'reply', reply: { id: `b${i + 1}`, title } })) } } }\n  : waText(msg.wa_id, reply);\n\nconst values = [CCOLS.map((c) => String(contact[c] || ''))];\nconst http = ctx.sheet_row\n  ? { method: 'PUT', url: sheetUrl(encodeURIComponent(contactRow(ctx.sheet_row))) + '?valueInputOption=RAW', body: { values } }\n  : { method: 'POST', url: sheetUrl(encodeURIComponent(contactsRange()) + ':append') + '?valueInputOption=RAW&insertDataOption=INSERT_ROWS', body: { values: ctx.has_header ? values : [CCOLS, ...values] } };\n\nconst known = (cfg.qualify || []).filter((q) => contact[q.key]).map((q) => `${q.label}: ${contact[q.key]}`);\nlet team = '';\nif (route === 'hot' || route === 'handoff' || route === 'to_manager') {\n  team = [\n    route === 'hot' ? 'Горячий клиент в WhatsApp' : route === 'to_manager' ? 'Новое сообщение клиента (разговор у менеджера)' : 'Нужен менеджер в WhatsApp',\n    `Клиент: ${contact.name || 'без имени'}, +${msg.wa_id}`,\n    reason && route !== 'to_manager' ? `Причина: ${reason}` : '',\n    `Сообщение: ${msg.text.slice(0, 800)}`,\n    summary ? `Кратко: ${summary}` : '',\n    ...known,\n    route !== 'to_manager' ? `Последнее в переписке:\\n${contact.history.split('\\n').slice(-6).join('\\n')}` : '',\n    'Ответить: ответом на это сообщение — текст уйдёт клиенту в WhatsApp.',\n    `WA: ${msg.wa_id}`,\n  ].filter(Boolean).join('\\n');\n}\nreturn [{ json: {\n  route, wa_id: msg.wa_id, problem,\n  client: { name: contact.name || '', phone: '+' + msg.wa_id, stage: contact.stage || '', need: contact.need || '', budget: contact.budget || '', timeline: contact.timeline || '' },\n  send: Boolean(message) && route !== 'silent' && route !== 'to_manager', message, graph_url: graphUrl(),\n  http, notify: Boolean(team), team_chat: cfg.team_chat_id, team_text: team, buttons_for_team: route === 'hot' || route === 'handoff',\n} }];\n"
      },
