    {
      "parameters": {
        "jsCode": "// Config — настройки. Меняйте значения справа от двоеточия.\nreturn [{ json: {\n  \"timezone\": \"Europe/Kyiv\",\n  \"locale\": \"ru-RU\",\n  \"sheets_api_base\": \"https://sheets.googleapis.com/v4\",\n  \"spreadsheet_id\": \"REPLACE_WITH_SPREADSHEET_ID\",\n  \"contacts_sheet\": \"Contacts\",\n  \"graph_api_base\": \"https://graph.facebook.com/v25.0\",\n  \"phone_number_id\": \"REPLACE_WITH_PHONE_NUMBER_ID\",\n  \"team_chat_id\": \"REPLACE_WITH_TEAM_CHAT_ID\",\n  \"handoff_hours\": 12\n} }];\n"
      },
