    {
      "parameters": {
        "method": "GET",
        "url": "={{ $json.sheets_api_base + '/spreadsheets/' + encodeURIComponent($json.spreadsheet_id) + '/values/' + encodeURIComponent(\"'\" + $json.contacts_sheet.replace(/'/g, \"''\") + \"'!A1:R\") }}",
