      "id": "00e2bf75-1ded-5910-a95a-c219e610789d",
      "name": "Read Contacts",
      "type": "n8n-nodes-base.httpRequest",
      "typeVersion": 4.2,
      "position": [
        -60,
        0
      ],
      "credentials": {
        "googleSheetsOAuth2Api": {
          "id": "REPLACE_ME",
          "name": "Google Sheets"
        }
      },
      "retryOnFail": true,
      "maxTries": 2,
      "waitBetweenTries": 1000
    },
    {
      "parameters": {
        "jsCode": "// Bridge — a manager answers a WhatsApp client from the Telegram team chat, takes the client, or gives them back to the bot.\nconst cfg = $('Config').first().json;\n// ---- shared helpers ----\nconst MIN = 60000;\nconst nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());\nconst digitsOf = (value) => String(value || '').replace(/[^\\d]/g, '');\n// Phones are stored in one international form, so the same person is recognised however they typed it.\nfunction phoneOf(value) {\n  const rules = cfg.phone || {};\n  let d = digitsOf(value);\n  if (d.startsWith('00')) d = d.slice(2);\n  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {\n    d = rules.country_code + d.slice(rules.national_prefix.length);\n  }\n  return d.length >= 9 && d.length <= 15 ? '+' + d : '';\n}\nfunction emailOf(value) {\n  const e = String(value || '').trim().toLowerCase();\n  return /^[^\\s@<>()\",;]+@[^\\s@<>()\",;]+\\.[a-z]{2,}$/.test(e) ? e : '';\n}\nconst localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {\n  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',\n}).format(new Date(ms));\nfunction localParts(ms) {\n  const parts = {};\n  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;\n  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };\n}\nconst sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;\nconst quoteSheet = (name) => \"'\" + String(name).replace(/'/g, \"''\") + \"'\";\n// Contacts sheet: one row per WhatsApp number. The sheet may start empty: the header is written with the first contact.\nconst CCOLS = ['wa_id', 'name', 'phone', 'first_seen', 'last_in_at', 'last_out_at', 'status', 'stage', 'need', 'budget', 'timeline', 'details',\n  'hot', 'handoff_until', 'followup_sent', 'history', 'manager', 'notes'];\nconst colLetter = (index) => { let s = ''; let n = index + 1; while (n) { const r = (n - 1) % 26; s = String.fromCharCode(65 + r) + s; n = Math.floor((n - 1) / 26); } return s; };\nconst CLAST = colLetter(CCOLS.length - 1);\nconst contactsRange = () => `${quoteSheet(cfg.contacts_sheet)}!A1:${CLAST}`;\nconst contactRow = (row) => `${quoteSheet(cfg.contacts_sheet)}!A${row}:${CLAST}${row}`;\nconst waBatchUrl = () => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values:batchGet?ranges=${encodeURIComponent(contactsRange())}&ranges=${encodeURIComponent(`${quoteSheet(cfg.catalog_sheet)}!A1:C`)}`;\nconst contactsTable = (values) => { const rows = values || []; const header = rows.length && rows[0][0] === 'wa_id'; return { header, rows: header ? rows.slice(1) : [] }; };\nconst ccell = (row, c) => row[CCOLS.indexOf(c)] || '';\nconst contactObject = (row) => Object.fromEntries(CCOLS.map((c) => [c, ccell(row, c)]));\nconst graphUrl = () => `${cfg.graph_api_base}/${encodeURIComponent(cfg.phone_number_id)}/messages`;\nconst waText = (to, body) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to, type: 'text', text: { preview_url: false, body: String(body).slice(0, 4000) } });\nconst update = $('Telegram Trigger').first().json;\nconst table = contactsTable($input.first().json.values);\nconst now = nowMs();\nconst iso = new Date(now).toISOString();\nconst team = String(cfg.team_chat_id);\nconst out = (json) => [{ json: Object.assign({ act: false, send: false, write: false, note: '', callback_id: '', team_chat: cfg.team_chat_id, graph_url: graphUrl() }, json) }];\n\nlet action = '', waId = '', text = '', who = '', callbackId = '';\nconst cb = update.callback_query;\nif (cb) {\n  if (String(cb.message && cb.message.chat && cb.message.chat.id) !== team) return out({});\n  [action, waId] = String(cb.data || '').split(':');\n  who = [cb.from.first_name, cb.from.last_name].filter(Boolean).join(' ') || cb.from.username || '';\n  callbackId = cb.id;\n} else if (update.message && String(update.message.chat.id) === team && update.message.text) {\n  const quoted = (update.message.reply_to_message || {}).text || '';\n  const ref = /WA: (\\d{6,15})/.exec(quoted);\n  if (!ref) return out({});\n  action = 'reply'; waId = ref[1]; text = update.message.text.slice(0, 4000);\n  who = [update.message.from.first_name, update.message.from.last_name].filter(Boolean).join(' ');\n} else return out({});\nif (!['reply', 'take', 'bot'].includes(action) || !waId) return out({});\n\nconst index = table.rows.findIndex((r) => ccell(r, 'wa_id') === waId);\nif (index < 0) return out({ act: true, note: `Клиент +${waId} не найден в таблице`, callback_id: callbackId });\nconst c = contactObject(table.rows[index]);\nconst write = (extra) => ({ write: true, http: { method: 'PUT', url: sheetUrl(encodeURIComponent(contactRow(index + (table.header ? 2 : 1)))) + '?valueInputOption=RAW', body: { values: [CCOLS.map((k) => String(c[k] || ''))] } }, ...extra });\n\nif (action === 'bot') {\n  c.status = 'bot'; c.handoff_until = '';\n  return out(Object.assign({ act: true, note: `Клиент +${waId} снова с ботом`, callback_id: callbackId }, write({})));\n}\nc.status = 'manager';\nc.manager = who || c.manager;\nc.handoff_until = new Date(now + (cfg.handoff_hours || 12) * 60 * MIN).toISOString();\nif (action === 'take') return out(Object.assign({ act: true, note: `${who || 'Менеджер'} ведёт клиента +${waId}. Бот молчит ${cfg.handoff_hours || 12} ч.`, callback_id: callbackId }, write({})));\n\n// WhatsApp allows free-form messages only within 24 hours of the client's last message.\nconst lastIn = Date.parse(c.last_in_at);\nif (isNaN(lastIn) || now - lastIn > 24 * 60 * MIN) {\n  return out({ act: true, note: `Не отправлено: с последнего сообщения клиента прошло больше 24 часов. WhatsApp разрешает только одобренный шаблон — напишите клиенту из инструмента рассылок или позвоните: +${waId}.` });\n}\nc.last_out_at = iso;\nc.history = `${c.history ? c.history + '\\n' : ''}${localText(now)} · ${who || 'менеджер'}: ${text.replace(/\\n+/g, ' ').slice(0, 400)}`.slice(-3500);\nreturn out(Object.assign({ act: true, send: true, message: waText(waId, text), note: `Отправлено в WhatsApp: +${waId}` }, write({})));\n"
      },
