      "parameters": {
        "jsCode": "// Not Delivered — WhatsApp refused the message (most often: more than 24 hours since the client wrote). A person must act.\nconst sent = $('Bridge').first().json;\nconst error = $input.first().json.error || $input.first().json;\nconst raw = JSON.stringify(error);\nconst window = /131047|re-engagement/i.test(raw);\nreturn [{ json: { text: [\n  'Сообщение в WhatsApp не доставлено',\n  `Клиент: +${sent.wa_id || (sent.message || {}).to || '—'}`,\n  window ? 'Причина: прошло больше 24 часов с последнего сообщения клиента — WhatsApp разрешает только одобренный шаблон.' : `Ошибка: ${raw.slice(0, 300)}`,\n  `Текст: ${(((sent.message || {}).text || {}).body || ((((sent.message || {}).interactive || {}).body) || {}).text || '').slice(0, 600)}`,\n].join('\\n') } }];\n"
